      made++;
      const hopeless = err && err.name === 'UnrecoverableError';
      if (hopeless || made >= attempts) return { state: 'failed', attemptsMade: made, failedReason: err.message, at };
      const wait = !b ? 0 : b.type === 'exponential' ? b.delay * 2 ** (made - 1) : b.delay;
